<div elname="livefield-elem" reltype="parent" id="TermsConditions3-li" fldtype="34" comptype="34" compname="TermsConditions3" linkname="TermsConditions3" needdata="true" mandatory="true" statustext="Agreed" class="fieldWrapper" page_no="1" page_link_name="first" showlabel="true" seqno="13" counterUID=""><div class="fieldContainer  termsConditionsCont "><div class="zfLabelDiv ">
<label class="fieldlabel" id="TermsConditions3-arialabel">

<span class="fieldLabelTxt  advLabelName"><div><span class="size" style="font-size: 16px"><b><u><i>Declaration cum Certification cum Consent</i></u></b></span><br/></div></span> 
<em class="important" aria-hidden="true" >
*
</em>

<span class="sr-only">Required</span> 
</label>
</div><div elname="zfFieldDiv" class="zfFieldDiv_cont"><div class="fieldtypeText" ><div class="termsContainer">
<div id="TermsConditions3-arialabel-terms"elname="terms"aria-labelledby="TermsConditions3-arialabel TermsConditions3-arialabel-terms"role="group" class="termsMsg descFld termScrollRemove"><div class="align-justify" style="text-align: justify"><span class="size" style="font-size: 13.333px">I, the undersigned, hereby certify that all the information provided by me in this Personal Information &amp; Declaration Form is true, complete, and accurate to the best of my knowledge and belief. I also declare that I am mentally, physically, and legally fit to perform the duties and responsibilities associated with my job role at ETERNAL HR SERVICES PVT LTD. I further authorize ETERNAL HR SERVICES PVT LTD (hereinafter referred to as “the Company”) to register, store, &amp; process all personal information provided by me in this form, including but not limited to my email address, mobile number, personal details, &amp; bank account information. I authorize the Company to share such details with relevant regulatory or compliance authorities as may be required, in accordance with applicable laws. I hereby consent to receive all communications and transactions, including but not limited to my appointment letter, payslips, salary, reimbursements, duties, policies, documents, terms &amp; conditions, rules, regulations, &amp; notifications, in electronic form, as permitted under the Information Technology Act, 2000 &amp; any amendments thereto. This authorization shall remain effective throughout the duration of my employment with the Company &amp; shall continue to be valid even after the termination of my employment. I agree that the Company's dispatch log reports will serve as conclusive evidence of delivery of any electronic communication, &amp; such communication shall be deemed to have been received by me, notwithstanding any delays or non-receipt. Furthermore, I acknowledge &amp; agree that the absence of a bounced email notification or a failed fund transfer notice shall be treated as successful delivery to my registered email address or bank account, respectively. I understand that, for the purpose of receiving such communications &amp; transactions, it is my responsibility to maintain an active mobile number for SMS alerts, a valid email address for electronic communications, &amp; a functional bank account for financial transactions. I confirm that the details provided in this form are accurate &amp; active &amp; hereby request the Company to activate the necessary SMS, email, &amp; bank transfer settings under my employee code. I certify that neither ETERNAL HR SERVICES PVT LTD nor its clients shall be responsible for any of my illegal actions or legal liabilities, including but not limited to loans, recoveries, etc. I hereby declare that I will promptly inform the Company &amp; all relevant authorities, such as ESIC, EPF, PTAX, Income Tax, etc., in writing within 24 hours of any changes to my email address or mobile number. I acknowledge that the Company reserves the right, at its sole discretion, to discontinue this service at any time without prior notice, whether through its website or any other communication channel. I understand that I am solely responsible for maintaining the security &amp; confidentiality of my mobile phone, mobile number, computer, laptop, &amp; email address used in connection with this service. I further acknowledge that any unauthorized access to or misuse of these devices or contact information will be my sole responsibility. I have read &amp; fully understood the terms &amp; conditions set forth on the Company’s website (</span><a href="http://www.eternalhr.com" target="_blank" rel="noopener noreferrer"><span class="size" style="font-size: 13.333px">www.eternalhr.com</span></a><span class="size" style="font-size: 13.333px">), &amp; I agree to be bound by these terms, as they may be amended from time to time. My continued use of the Company’s services &amp; facilities shall constitute my acceptance of such terms &amp; conditions, including any subsequent modifications. In case any of the information provided is found incorrect or incomplete, I shall be solely responsible for the consequences, &amp; the Company will not have any liability. Furthermore, the Company reserves the right to take disciplinary action against me, which may extend to termination of employment at any time in the future without notice or compensation in lieu thereof.</span> <br/></div></div>
<div class="termsAccept customCheckBox"><input aria-labelledby="TermsConditions3-arialabel TermsConditions3-arialabel-declaration"aria-describedby="error-TermsConditions3"tabindex="0" onmousedown="event.preventDefault();" elname="statusCB" id="TermsConditions3-input" class="checkBoxType flLeft" name="TermsConditions3" type="checkbox" onchange="ZFLive.hideClosestFieldElemErrorDiv(this);" ><label class="cusChoiceLabel" for="TermsConditions3-input"></label>
<div class="descFld" id="TermsConditions3-arialabel-declaration"><div><span style="outline: none; margin: 0px; padding: 0px; border: 0px; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; box-sizing: border-box; letter-spacing: normal; orphans: 2; text-align: left; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: normal; background-color: rgb(245, 247, 247); text-decoration-color: initial" class="fieldLabelTxt  advLabelName"><div style="font-variant: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; outline: none; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; display: inline"><span style="outline: none; margin: 0px; padding: 0px; border: 0px; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline"><span style="outline: none; margin: 0px; padding: 0px; border: 0px; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline"><span style="font-variant: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; outline: none; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline"><span style="font-family: inherit; font-style: inherit; font-weight: inherit; outline: none; margin: 0px; padding: 0px; border: 0px; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; box-sizing: border-box; font-size: 13.333px" class="size">I certify and give my consent on this declaration</span></span></span></span></div></span><br/></div></div></div></div></div><div class="zfErrorParentDiv"><div id="error-TermsConditions3" elname="error" class="zfErrorDiv" style="display:none" name="errDiv"></div></div></div></div></div>


<div elname="livefield-elem" reltype="parent" id="TermsConditions1-li" fldtype="34" comptype="34" compname="TermsConditions1" linkname="TermsConditions1" needdata="true" mandatory="false" statustext="Requested for exemption" class="fieldWrapper" page_no="1" page_link_name="first" showlabel="true" seqno="14" counterUID=""><div class="fieldContainer  termsConditionsCont "><div class="zfLabelDiv ">
<label class="fieldlabel" id="TermsConditions1-arialabel">

<span class="fieldLabelTxt  advLabelName"><div><b><i><u><span class="size" style="font-size: 18.667px">EPF Exemtion Request</span></u></i></b><br/></div></span> 
</label>
</div><div elname="zfFieldDiv" class="zfFieldDiv_cont"><div class="fieldtypeText" ><div class="termsContainer">
<div class="termsAccept customCheckBox"><input aria-labelledby="TermsConditions1-arialabel TermsConditions1-arialabel-declaration"aria-describedby="error-TermsConditions1"tabindex="0" onmousedown="event.preventDefault();" elname="statusCB" id="TermsConditions1-input" class="checkBoxType flLeft" name="TermsConditions1" type="checkbox" onchange="ZFLive.hideClosestFieldElemErrorDiv(this);" ><label class="cusChoiceLabel" for="TermsConditions1-input"></label>
<div class="descFld" id="TermsConditions1-arialabel-declaration"><div class="align-justify" style="text-align: justify">I declare that I have never been a member of &quot;Employee Provident Fund Scheme&quot; till now. I also declare that&nbsp; I don't have any amount outstanding or dues with &quot;Employee Provident Fund&quot; during my last assignments. I request the organization to kindly exempt me from &quot;Employee Provident Fund&quot; scheme. <br/></div><div class="align-justify" style="text-align: justify">I'm making this request knowingly benefits of EPF Scheme and under no pressure as such. I've signed and submitted Form 11 for exemption from &quot;Employee Provident Fund&quot;.<br/></div></div></div></div></div><div class="zfErrorParentDiv"><div id="error-TermsConditions1" elname="error" class="zfErrorDiv" style="display:none" name="errDiv"></div></div></div></div></div>


<div elname="livefield-elem" reltype="parent" id="TermsConditions2-li" fldtype="34" comptype="34" compname="TermsConditions2" linkname="TermsConditions2" needdata="true" mandatory="false" statustext="Agreed" class="fieldWrapper" page_no="1" page_link_name="first" showlabel="true" seqno="15" counterUID=""><div class="fieldContainer  termsConditionsCont "><div class="zfLabelDiv ">
<label class="fieldlabel" id="TermsConditions2-arialabel">

<span class="fieldLabelTxt  advLabelName"><div><span class="size" style="font-size: 16px"><b><i><u>TERMS OF APPOINTMENT WITH ETERNAL HR SERVICES PVT. LTD.</u></i></b></span><br/></div></span> 
</label>
</div><div elname="zfFieldDiv" class="zfFieldDiv_cont"><div class="fieldtypeText" ><div class="termsContainer">
<div id="TermsConditions2-arialabel-terms"elname="terms"aria-labelledby="TermsConditions2-arialabel TermsConditions2-arialabel-terms"role="group" class="termsMsg descFld termScrollRemove"><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">We are pleased to engage you in ETERNAL HR SERVICES PVT. LTD. (herein after &quot;company&quot;) as per the following terms and conditions on fixed term contract basis. The terms and conditions of your engagement are outlined below and will govern your relationship with the Company throughout the duration of your employment.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">1    You engagement with the Company is for a fixed term commencing from [Date of Joining] to [Date of Expiry]. Upon expiration of this term, your employment will automatically terminate without any further written or verbal communication. If your contract is not renewed upon expiration, you shall have no right or entitlement to continued employment or to claim regularization or permanency in the Company. Contract renewal will only occur through written communication from the Company. In the absence of a written renewal, you will be considered on a month-to-month contract basis, and you will not be entitled to any claim of permanent employment thereafter.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">2    You have to complete your joining formalities within 3 days of your joining including submission of complete &amp; correctly filled welcome kit, address proof, age proof, Photo ID, Aadhaar card, UAN No., old ESIC No. Bank Account proof etc. You shall keep the Company and the deputed client informed of any change in your postal address, otherwise the last address communicated by you to the company or available in the Company’s and the deputed client record will be deemed as your postal address for the purpose of all communication from the Company or the deputed client. Any communication sent through any mode to your postal address would be considered as acknowledged by you irrespective of its return to office.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">3    You have to render your services to the above-mentioned deputed client, at their premises. Your working location would be temporary and you are liable to be shifted from one job or department or city or state or client to another in accordance with the business exigencies /managerial requirements and you have to adhere to such changes without any delay and objection. if you do not give your consent or reported at transferred place within the given time, it will be deemed that you are not interested in the employment with our company and your contract will be treated as cancelled, null and void immediately without any notice or any compensation in lieu thereof and your name will be struck off from our payroll/attendance register.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">4    Since you are being engaged for a fixed period as mentioned above, you agree that you will neither have any right (including but not limited to permanent job) nor a lien on the job held by you.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">5    i)&nbsp;During your tenure you may leave the services by giving prior notice of [noticePeriod] days or pay in lieu to Company Similarly, Company may terminate your services by giving you prior notice of [noticePeriod] days or pay in lieu. However, in case of business exigencies company shall have full rights to terminate your contract prior to the end date without giving notice or pay in lieu of notice period. You agree that in such event you shall not claim or raise any dispute for non-payment of notice period.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">ii)&nbsp;In event of your resigning the company at its sole discretion can relieve you of your services with immediate effect without giving you the notice period pay.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">6    You have to faithfully perform your duties and services in a professional manner exclusively to the deputed Client, their employees, representatives and such performance shall not be inconsistent with any obligation you may have to other third parties. Your performance will be reviewed regularly and at any point of time if the performance is not found to be satisfactory, Company will be free to end the contract immediately without any notice or compensation for the same even before the contract ending date as specified above. Decision to re-engage your services is entirely at the discretion of the deputed client or the company.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">7    You shall not engage yourself into any conduct which is detrimental to the interest of deputed Client, Indian law or our Company.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">a)&nbsp;&nbsp;You acknowledges that, in the course of performing and fulfilling your duties hereunder, you may have access to and be entrusted with confidential information (included but not limited to any trade secret or other information which is confidential or commercially sensitive in nature, relates to the business methods, management systems, marketing plans, strategic plans, finances, new or maturing business opportunities, marketing activities, processes, inventions, designs or similar of any Group Company, or to which any Group Company owes a duty of confidentiality to any third party (includes other employees who do not need such information in their work)) of the company/deputed client, the disclosure of any of the confidential information to the competitors of the company/deputed client would be highly detrimental to the interests of the Employer.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">b) You further acknowledges and agrees that the right to maintain the confidentiality of trade secrets, source code, website information, business plans or client information or other confidential or proprietary information, for the purpose of enabling the other party such information constitutes a proprietary right which the company/deputed client is entitled to protect.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">c)&nbsp;&nbsp;Accordingly, you covenants and agrees with the company/deputed client that you will not, under any circumstance during and after the continuance of this agreement, disclose any such confidential information to any person, firm or corporation, nor shall you use the same, except as required in the normal course of your engagement hereunder.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">d)&nbsp;The company/deputed client owns any intellectual property created by you during the course of the employment, or in relation to a certain field, and you shall thereon have all the necessary rights to retain it. After termination of your employment, you shall not impose any rights on the intellectual property created. Any source code, software or other intellectual property developed, including but not limited to website design or functionality that was created by you, during the course of employment under this Agreement, shall belong to the company/deputed client.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">8    You are not allowed to receive any payment or kind of any nature, either directly or indirectly from the deputed Client, co-employees, representatives or any other third party unless authorized by company in writing.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify" class="ql-align-justify"><span class="font" style="font-family: inherit"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">9    You are bound to comply with the safety, health, the service rules in force and amended by the deputed client or by company from time to time in relation to your service conditions, which will form part of your terms of contract.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">10    You will not take any leave without prior written approval from your reporting manager. Any unapproved Leave for more than 3 consecutive days shall be treated as willfull resignation. Such event will be deemed that you are not interested in the employment with our company and your contract will be treated as cancelled, null and void immediately without any notice or any compensation in lieu thereof and your name will be struck off from our payroll / attendance register.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">11    You agree to defend, indemnify and hold our Company and the deputed Client harmless from any and all claims, damages, liability, attorney’s fees, environmental penalties, fines and expenses on account of your failure to satisfy any of your duties, obligations under this contract, legal dues of your previous jobs, inappropriate action, misconduct or violation of any law, agreement, or otherwise.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">12    You will be responsible for safe keeping and return in good condition and order all the office properties, equipment, instruments, tools, books etc. which may be given to you for your use, custody and charge during your job. The Company and the deputed client have the right to deduct the money along with all such things from your dues and take such other action as the Company and the deputed client may deem proper in the event of failure to account for the aforesaid properties to the satisfaction of the Company and the deputed client.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">13    Any dispute between you and the deputed Client / company shall be referred to a Sole Arbitrator appointed by the company. The arbitration shall be conducted in the English language, in accordance with the Arbitration &amp; Conciliation Act, 1996, within your deputed working city. Your failure to attend and participate in the said proceedings will amount to sufficient compliance with principles of natural justice. Hence, the Arbitration proceedings may be held in your absence viz. Ex-party. Please note that any other Courts jurisdiction shall stand specifically barred.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">14    You will be paid State Minimum Wages or as agreed at the time of your joining. All statutory dues arising out of your monthly compensation package will be deducted and deposited with the concerned government authorities accordingly. These statutory dues may include PF / ESIC / LWF / TDS / PTAX etc. You can get your salary details from Annexure-1. In the event of overpayment, this may be rectified and adjusted in the subsequent payment months or you may be asked to refund the excess amount immediately.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">15    Your contract is coterminous with the contract between deputed client you are deputed and Company. You will be paid only as per the payouts approved and provided by the deputed client. You will be paid full and final payment (if any) within 30 days from your date of leaving or date of receiving your resignation and no dues certificate from your supervisor whichever is later.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">16    * Your net take home amount will be affected by prevailing laws like Income Tax, LWF, Professional Tax and other state level compliance contributions as applicable. Company has the authority to change or remove any or the entire allowance\ reimbursement components without any written or verbal communication\confirmation to\from you.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">17    All your rights and obligations in the course of this contract are strictly limited to the terms and conditions of this contract. Accordingly, except as specifically indicated in this contract, you will not be entitled to any other benefits, subsidy, allowances or compensation from the deputed Client/company.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">18    Your contract can be terminated earlier also by the Staffing Agency company without any notice or payment of any kind In lieu of notice, if:-</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">a.&nbsp;You are found&nbsp;indulging&nbsp;in&nbsp;any&nbsp;act&nbsp;of&nbsp;dishonesty,&nbsp;disobedience, Insubordination, incivility, intemperance, irregularity in attendance or other misconduct or neglect of duty or incompetence on your part in the discharge of your duties or the breach on your part of any of the terms, conditions or stipulations contained in this letter or a violation on your part of any of the Deputed Client/company's service rules &amp; regulations.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inher