any.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; vertical-align: baseline; cursor: text; box-sizing: border-box; text-align: justify; letter-spacing: 0.3px; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: pre-wrap; text-decoration-color: initial" class="ql-align-justify"><span class="font" style="font-family: Arimo"><span class="font" style="font-family: inherit"><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px">d.&nbsp;You may also choose to terminate this contract by giving one week notice in writing or if no notice is submitted and you remain absent continuously for 8 days then it will be deemed that you are not interested in the employment with our organisation and as such your contract will be treated as cancelled, null and void and your name will be struck off from our payroll/attendance register.</span></span></span></span><span class="colour" style="color: rgb(0, 0, 0)"><span class="highlight" style="background-color: rgb(255, 255, 255)"><span class="size" style="background-color: inherit; font-size: 13.333px"><br/></span></span></span></span></p><p style="margin: 0px; padding: 0px; border: 0px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-position: inherit; font-weight: 400; font-stretch: inherit; line-height: inherit